/**
 * @description : Bottom Navigation Bar for institute_user (mobile app)
 *                Renders tabs based on cds permission flags.
 * @author : Bala Krishna
 * @date   : 16-01-2023  (redesigned Aug-2026)
 */

import React, { useContext } from 'react';
import {
  FaTachometerAlt,
  FaUserCircle,
  FaBookOpen,
} from 'react-icons/fa';
import { Link, useLocation } from 'react-router-dom';
import { AuthContext } from '../../App';
import {
  hasAnyPermission,
  USER_PORTAL_PERMISSIONS,
} from '../../services/commonUtills/FormValidations';

const NavBar = () => {
  const location = useLocation();
  const { stateAuth } = useContext(AuthContext);
  const user = stateAuth?.user || {};
  const userType = String(user.typ || '').toUpperCase();
  const canViewProfile =
    ['STUDENT', 'STAFF'].includes(userType) &&
    hasAnyPermission(user.cds, USER_PORTAL_PERMISSIONS.PROFILE);
  const canViewHomework =
    ['STUDENT', 'STAFF'].includes(userType) &&
    hasAnyPermission(user.cds, USER_PORTAL_PERMISSIONS.HOMEWORK);
  const profilePath = userType === 'STAFF' ? '/staff-profile' : '/profile';

  const isActive = (path) => location.pathname === path;

  return (
    <nav className="user-bottom-nav">

      {/* Dashboard – always visible */}
      <Link
        to="/dashboard"
        className={`user-bottom-nav-item${isActive('/dashboard') ? ' active' : ''}`}
      >
        <FaTachometerAlt className="user-bottom-nav-icon" />
        <span>Home</span>
      </Link>

      {/* My Profile — I_N_U_S */}
      {canViewProfile && (
        <Link
          to={profilePath}
          className={`user-bottom-nav-item${isActive(profilePath) ? ' active' : ''}`}
        >
          <FaUserCircle className="user-bottom-nav-icon" />
          <span>Profile</span>
        </Link>
      )}

      {/* Home Work — H_W_M */}
      {canViewHomework && (
        <Link
          to="/homework"
          className={`user-bottom-nav-item${isActive('/homework') ? ' active' : ''}`}
        >
          <FaBookOpen className="user-bottom-nav-icon" />
          <span>Homework</span>
        </Link>
      )}

    </nav>
  );
};

export default NavBar;
